mapper.select:
/* 모델별/상세스펙 검색 */ SELECT msc.spec_content_no, msc.manager_id, m.model_nm, ps.spec_nm, msc.spec_content, msc.register_date, msc.revision_date, msc.use_status FROM model_spec_content msc inner join model m on msc.MODEL_NO = m.MODEL_NO inner join products_spec ps using(spec_no)
${searchKey} LIKE CONCAT('%', #{searchValue}, '%')
AND msc.use_status = #{useStatus}
ORDER BY CAST(SUBSTRING_INDEX(spec_content_no, '_', -1) AS UNSIGNED);

/* 카테고리별/상세스펙 검색 */ SELECT ps.spec_no, ps.manager_id, pc.small_category, ps.spec_nm, ps.register_date, ps.revision_date, ps.use_status FROM products_spec ps inner join products_category pc using(product_category_no)
${searchKey} LIKE CONCAT('%', #{searchValue}, '%')
AND ps.use_status = #{useStatus}
ORDER BY CAST(SUBSTRING_INDEX(spec_no, '_', -1) AS UNSIGNED);

/* 전체혜택 검색 */ SELECT benefit_no, manager_id, benefit_nm, register_date, revision_date, use_status FROM benefit
${searchKey} LIKE CONCAT('%', #{searchValue}, '%')
AND use_status = #{useStatus}
ORDER BY CAST(SUBSTRING_INDEX(benefit_no, '_', -1) AS UNSIGNED);

/* 모델 검색 */ SELECT m.model_no, m.manager_id, b.brand_nm, i.item_nm, pc.small_category, m.model_nm, m.register_date, m.revision_date, m.use_status FROM model m inner join products_category pc using(product_category_no) inner join item i using(item_no) left join brand b using(brand_no)
${searchKey} LIKE CONCAT('%', #{searchValue}, '%')
AND m.use_status = #{useStatus}
ORDER BY CAST(SUBSTRING_INDEX(model_no, '_', -1) AS UNSIGNED);

/* 품목 검색 */ SELECT i.item_no, i.manager_id, pc.small_category, i.item_nm, i.register_date, i.revision_date, i.use_status FROM item i inner join products_category pc using(product_category_no)
${searchKey} LIKE CONCAT('%', #{searchValue}, '%')
AND i.use_status = #{useStatus}
ORDER BY CAST(SUBSTRING_INDEX(item_no, '_', -1) AS UNSIGNED);

/* 브랜드 검색 */ SELECT brand_no, manager_id, brand_nm, register_date, revision_date, use_status FROM brand
${searchKey} LIKE CONCAT('%', #{searchValue}, '%')
AND use_status = #{useStatus}
ORDER BY CAST(SUBSTRING_INDEX(brand_no, '_', -1) AS UNSIGNED);

/* 카테고리 검색 */ SELECT product_category_no, manager_id, large_category_no, large_category, middle_category_no, middle_category, small_category, register_date, revision_date, use_status FROM products_category
${searchKey} LIKE CONCAT('%', #{searchValue}, '%');
AND use_status = #{useStatus}

mapper.delete:
/* 모델별/상세스펙 삭제 */
DELETE
FROM
	model_spec_content
WHERE
	spec_content_no = #{modelSpecNo};

/* 카테고리별/상세스펙 삭제 */
DELETE
FROM
	products_spec
WHERE
	spec_no = #{specNo};

/* 전체혜택 삭제 */
DELETE
FROM
	benefit
WHERE
	benefit_no = #{benefitNo};

/* 모델 삭제 */
DELETE
FROM
	model
WHERE
	model_no = #{modelNo};

/* 품목 삭제 */
DELETE
FROM
	item
WHERE
	item_no = #{itemNo};

/* 브랜드 삭제 */
DELETE 
FROM 
	brand
WHERE 
	brand_no = #{brandNo};

/* 카테고리 삭제 */
DELETE
FROM
	products_category
WHERE
	product_category_no = #{categoryNo};

mapper.select:
 /* 모델별/상세스펙(모델 + 스펙 + 상세스펙내용) 중복체크 */
	SELECT
		CASE WHEN COUNT(*) > 0 THEN true ELSE false END
	FROM
		model_spec_content
	WHERE
		spec_content = #{modelSpecName}
		AND model_no = #{modelNo}
		AND spec_no = #{specNo};

/* 카테고리별/상세스펙(카테고리 + 스펙명) 중복체크 */
SELECT
	CASE WHEN COUNT(*) > 0 THEN true ELSE false END
FROM
	products_spec
WHERE
	spec_nm = #{specName}
	AND product_category_no = #{categoryNo};

/* 모델(카테고리 + 브랜드 + 품목 + 모델명) 중복체크 */
SELECT
	CASE WHEN COUNT(*) > 0 THEN true ELSE false END
FROM
	model
WHERE
	model_nm = #{modelName}
	AND product_category_no = #{categoryNo}
	AND brand_no = #{brandNo}	
	AND item_no = #{itemNo};

/* 품목(카테고리 + 품목명) 중복체크 */
SELECT
	CASE WHEN COUNT(*) > 0 THEN true ELSE false END
FROM
	item
WHERE
	item_nm = #{itemName}
	AND product_category_no = #{categoryNo};

/* 카테고리(대분류 + 중분류 + 소분류) 중복체크 */
SELECT
	CASE WHEN COUNT(*) > 0 THEN true ELSE false END
FROM
	products_category
WHERE
	large_category = #{lgCategory}
	AND middle_category = #{mdCategory}
	AND small_category = #{smCategory};
